function determineResult(cat1, cat2, cat3, cat4) {
    if (cat1 > 0 && cat2 > 0 && cat3 > 0 && cat4 > 0) return 5;
    if (cat1 + cat2 > cat3 + cat4) return cat1 > cat2 ? 1 : 2;
    return cat3 > cat4 ? 3 : 4;
  }

